const links=[...document.querySelectorAll('.case-nav nav a')];const sections=[...document.querySelectorAll('.case-main>section')];function update(){const offset=innerWidth<=600?130:80;let current=sections[0];for(const section of sections)if(section.getBoundingClientRect().top<=offset)current=section;for(const link of links){const active=link.hash==='#'+current.id;link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current')}const length=document.documentElement.scrollHeight-innerHeight;const progress=length>0?Math.min(100,Math.round(scrollY/length*100)):100;document.querySelector('#case-progress').textContent=String(progress).padStart(2,'0')+'%';document.querySelector('.case-nav-bottom i').style.width=progress+'%'}let queued=false;addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(()=>{update();queued=false})}},{passive:true});addEventListener('resize',update);addEventListener('load',update);update();
